class UndergroundSystem {
public:
    void checkIn(int card, const std::string& station, int time) {
        riding_[card] = {station, time};
    }

    void checkOut(int card, const std::string& station, int time) {
        auto [start, startTime] = riding_.at(card);
        riding_.erase(card);
        auto& [total, count] = routes_[{start, station}];
        total += time - startTime;
        count++;
    }

    double getAverageTime(const std::string& start, const std::string& end) const {
        auto it = routes_.find({start, end});
        if (it == routes_.end()) {
            return -1;
        }
        return static_cast<double>(it->second.first) / it->second.second;
    }

