class UndergroundSystem {
    // Each rider's check-in station and time, by card id, while they ride.
    private final Map<Integer, String> startStation = new HashMap<>();
    private final Map<Integer, Integer> startTime = new HashMap<>();
    // Each route's total trip time and trip count, by "start end".
    private final Map<String, Integer> totalTime = new HashMap<>();
    private final Map<String, Integer> tripCount = new HashMap<>();

